"""Render the reviewed Classroom 50 assessment without claiming account-level adoption."""
from html import escape as E


def summary(data):
 a=data['classroom50_assessment']
 return '<aside class="classroom50-summary"><p class="pg-kicker">GitHub Classroom successor · checked October 13, 2026</p><h2>Classroom 50 is workable.<br>The compute limit remains.</h2><p>'+E(a['verdict'])+'</p><p>Course repositories and configuration can remain in our GitHub organization. The externally maintained application, GitHub services and Codespaces quotas still need a continuity plan.</p><a href="classroom50.html">Read the direct assessment and adoption checks ↗</a></aside>'


def assessment_view(data):
 a=data['classroom50_assessment'];e=data['evidence']
 rows=''.join('<tr><th scope="row">'+E(layer)+'</th><td>'+E(fit)+'</td><td>'+E(boundary)+'</td></tr>' for layer,fit,boundary in a['rows'])
 return '''<p class="pg-kicker">Direct consideration · GitHub Classroom successor</p><h1>Classroom 50.<br>A workable successor.</h1><p class="pg-lead">'''+E(a['verdict'])+'''</p><div class="pg-actions"><a class="pg-link primary" href="https://classroom50.org/" target="_blank" rel="noopener noreferrer">Visit Classroom 50 ↗</a><a class="pg-link" href="https://github.com/foundation50/classroom50">Project and documentation ↗</a><a class="pg-link" href="timeline.html#stage-canary">Place in the staged plan ↗</a></div><div class="pg-metrics"><div><strong>Workflow</strong><span>Assignments, submissions, feedback and grading</span></div><div><strong>External stewardship</strong><span>Fifty Foundation project and hosted app</span></div><div><strong>Same free quota</strong><span>No added Codespaces compute entitlement</span></div></div><p class="pg-note">Assessment status: '''+E(a['status'])+'''. “Successor” describes its functional role; it does not imply GitHub operates it or guarantees migration compatibility.</p><section><h2>Separate the layers.</h2><div class="pg-table"><table><thead><tr><th>Layer</th><th>What it provides</th><th>Our decision and boundary</th></tr></thead><tbody>'''+rows+'''</tbody></table></div><p class="pg-small">Verified eligible students can receive GitHub Pro benefits. Check the actual personal account, organization ownership and billing settings; do not carry forward a legacy GitHub Classroom Codespaces benefit without current confirmation. Stopped workspaces still consume storage. No payment method means access is blocked when included usage is exhausted.</p></section><section><h2>Keep the workflow portable.</h2><div class="classroom50-flow" aria-label="Separate assignment management from classroom computing"><div><span>01 · Coordinate</span><strong>Classroom 50</strong><p>Externally maintained interface</p></div><div><span>02 · Retain control</span><strong>Our GitHub organization</strong><p>Repositories, configuration and approved exports</p></div><div><span>03 · Run course work</span><strong>ACCESS CPU + GPU</strong><p>Proposed allocation, target replay and readiness</p></div></div><p>Use Classroom 50 where it saves course-lead effort. Keep versioned assignments and a rehearsed submission path that can operate without its hosted interface. Self-hosting is possible, but would add maintenance and authentication duties to a zero-cash program with limited hours.</p><p class="pg-note warning">No automatic ACCESS integration is claimed. The assignment-to-compute-to-submission path must be tested; approved LMS systems remain authoritative for grades.</p></section><section><h2>Before it becomes required.</h2><ol class="pg-checklist">'''+''.join('<li>'+E(x)+'</li>' for x in a['checks'])+'''</ol><p class="pg-small">These checks extend the existing submission/grade gate; all thirteen classroom gates remain planned, not run. Campus AWS stays CPU component-testing only; free GPU benchmarks precede the ACCESS pilot.</p></section><section><h2>Primary evidence.</h2><ul class="pg-refs">'''+''.join('<li><a href="'+E(e[k]['url'],quote=True)+'">'+E(e[k]['title'])+'</a> · <a href="evidence.html#'+k+'">Claim and scope</a></li>' for k in a['sources'])+'</ul></section>'


def report_text(data):
 a=data['classroom50_assessment'];e=data['evidence']
 text='\n\nCLASSROOM 50 SUCCESSOR ASSESSMENT | October 13, 2026\n\n'+a['verdict']+'\n'+a['status']+'\n'
 for layer,fit,boundary in a['rows']:text+='\n'+layer.upper()+'\n'+fit+'\n'+boundary+'\n'
 text+='\nBEFORE REQUIRED USE (NOT RUN)\n'+'\n'.join(str(i+1)+'. '+x for i,x in enumerate(a['checks']))+'\n\nCLASSROOM 50 PRIMARY SOURCES\n'
 for k in a['sources']:text+=e[k]['title']+'\n'+e[k]['url']+'\n'
 return text
